WITH inner_cte AS ( WITH DeptMaxUnits AS ( SELECT s.DEPARTMENT_NAME, MAX(c.TOTAL_UNITS) AS max_total_units, s.SCHOOL_NAME FROM SIS_SUBJECT_CODE s JOIN CIS_COURSE_CATALOG c ON s.DEPARTMENT_CODE = c.DEPARTMENT_CODE GROUP BY s.DEPARTMENT_NAME, s.SCHOOL_NAME HAVING MAX(c.TOTAL_UNITS) > 6 ), EECSStudents AS ( SELECT t2.FULL_NAME, t2.EMAIL_ADDRESS, t1.DEPARTMENT_NAME, t0.COURSE_DESCRIPTION, t0.COURSE_LEVEL, t2.STUDENT_YEAR FROM SIS_COURSE_DESCRIPTION t0 JOIN SIS_DEPARTMENT t1 ON t0.DEPARTMENT = t1.DEPARTMENT_CODE JOIN MIT_STUDENT_DIRECTORY t2 ON t1.DEPARTMENT_CODE = t2.DEPARTMENT WHERE t1.DEPARTMENT_NAME = 'Electrical Eng & Computer Sci' ) SELECT dmu.DEPARTMENT_NAME, dmu.max_total_units, dmu.SCHOOL_NAME, es.FULL_NAME, es.EMAIL_ADDRESS, es.COURSE_DESCRIPTION, es.COURSE_LEVEL, es.STUDENT_YEAR FROM DeptMaxUnits dmu JOIN EECSStudents es ON dmu.DEPARTMENT_NAME = es.DEPARTMENT_NAME ) SELECT inner_cte.DEPARTMENT_NAME, inner_cte.max_total_units, inner_cte.SCHOOL_NAME, inner_cte.FULL_NAME, inner_cte.EMAIL_ADDRESS, inner_cte.COURSE_DESCRIPTION, inner_cte.COURSE_LEVEL, mode_stats.Most_Common_Student_Year FROM inner_cte JOIN ( SELECT COURSE_LEVEL, STUDENT_YEAR AS Most_Common_Student_Year FROM ( SELECT COURSE_LEVEL, STUDENT_YEAR, COUNT(*) AS cnt, ROW_NUMBER() OVER (PARTITION BY COURSE_LEVEL ORDER BY COUNT(*) DESC) AS rn FROM inner_cte GROUP BY COURSE_LEVEL, STUDENT_YEAR ) ranked WHERE rn = 1 ) mode_stats ON inner_cte.COURSE_LEVEL = mode_stats.COURSE_LEVEL